from pathlib import Path
import json,re,shutil
R=Path('/workspace/work/deliverables/diecut');C=R/'collection/diecut';REF=Path('/workspace/work/reference');C.mkdir(parents=True,exist_ok=True)
T=json.load(open(REF/'contract/taxonomy.json'))
def write(p,s):p.parent.mkdir(parents=True,exist_ok=True);p.write_text(s)
