write(C/'kit/css/tokens.css','.slide {\n'+''.join(f'  {k}: {v};\n'for k,v in tokens.items())+'}\n.slide.dark { --page:#17191b; --ink:#f4f5f6; }\n')
write(C/'kit/description.md','Diecut translates an industrial automation proposal into a system of softly machined panels, capsule headers, precise fine rules, and circular sequence markers. Broad neutral plates hold compact, clearly ranked information; emphasis acts as a bright insert rather than decorative color.\n')
foundation='''*{box-sizing:border-box}.slide{width:1280px;height:720px;position:relative;overflow:hidden;background:var(--n-2);color:var(--ink);font-family:var(--font-body);font-weight:var(--body-weight);line-height:var(--body-line);letter-spacing:var(--body-track);padding:var(--furn-edge)}.slide .page{position:relative;width:100%;height:100%;background:var(--page);border-radius:var(--radius);padding:var(--margin-y) var(--margin-x);display:flex;flex-direction:column;gap:var(--gap-lg);isolation:isolate}.slide .page:before,.slide .page:after{content:'';position:absolute;width:16px;height:144px;top:calc(50% - 72px);background:var(--n-2);border-radius:999px;z-index:-1}.slide .page:before{left:0}.slide .page:after{right:0}.slide .head{flex:none;text-align:center;padding-top:var(--gap-sm)}.slide .kicker{display:flex;align-items:center;justify-content:center;border-radius:999px;background:var(--n-9);color:var(--page);margin:0 auto var(--gap-lg);min-height:var(--top-h);width:68%;font-size:var(--type-16);font-weight:var(--label-weight);line-height:var(--label-line);letter-spacing:var(--label-track)}.slide .title{margin:0;font-family:var(--font-display);font-size:var(--type-40);font-weight:var(--title-weight);line-height:var(--title-line);letter-spacing:var(--title-track)}.slide .lead{margin:var(--gap-sm) 0 0;font-size:var(--type-20);font-weight:var(--lead-weight);line-height:var(--lead-line);letter-spacing:var(--lead-track)}.slide .body{display:grid;grid-template-columns:repeat(12,minmax(0,1fr));grid-template-rows:repeat(6,minmax(0,1fr));gap:var(--gap);min-height:0;flex:1;container-type:size}.slide .body>*{min-width:0;min-height:0}.slide .group{display:flex;align-items:stretch;gap:var(--gap);min-width:0;min-height:0}.slide .group>*{flex:1;min-width:0;min-height:0}.slide .group.col,.slide .stack{display:flex;flex-direction:column;gap:var(--gap);min-height:0}.slide .stack>*{min-height:0;flex:1}.slide .group.two{display:grid;grid-template-columns:repeat(2,minmax(0,1fr))}.slide .group.three{display:grid;grid-template-columns:repeat(3,minmax(0,1fr))}.slide .split{display:grid;grid-template-columns:1fr 2fr;gap:var(--gap)}.slide .split.wide-left{grid-template-columns:2fr 1fr}.slide .seat{background:var(--n-2);border-radius:var(--radius-sm);display:flex;align-items:center;justify-content:center;min-width:0;min-height:0;aspect-ratio:1;color:var(--n-7);font-size:var(--type-18);position:relative}.slide .seat:before{content:attr(data-ph)}.slide .seat.avatar{border-radius:999px}.slide .seat.logo{aspect-ratio:1.5}.slide .seat.back{position:absolute;inset:0;aspect-ratio:auto;z-index:-1}.slide .icon{display:inline-block;flex:none;width:28px;height:28px}.slide.cover .page{display:flex;justify-content:center;padding:var(--margin-x)}.slide.cover .lockup{max-width:85%;z-index:1}.slide.cover .title{font-size:var(--type-72)}.slide.cover .kicker{width:max-content;min-width:240px;padding:var(--gap-sm) var(--pad);margin:0 0 var(--gap-lg)}.slide.cover .lead{font-size:var(--type-28)}.slide.cover .at-center{text-align:center;align-self:center}.slide.cover .at-center .kicker{margin-left:auto;margin-right:auto}.slide.cover .at-left{align-self:flex-start}.slide.cover .at-bottom-left{margin-top:auto}.slide.cover .at-top-left{margin-bottom:auto}.slide .meta{font-size:var(--type-16);margin-top:var(--gap-lg)}.slide .top,.slide .foot{display:flex;justify-content:space-between;align-items:center;font-size:var(--type-14);line-height:var(--label-line);font-weight:var(--label-weight)}.slide .foot{height:var(--foot-h)}.slide .rail{width:var(--rail-w)}.slide .deco{position:absolute;right:var(--margin-x);bottom:var(--margin-x);width:240px;height:240px;border:var(--stroke) solid var(--n-5);border-radius:999px}.slide .on{accent-color:var(--a1)}'''
